// One-factor diagnosis. Appearance-changing variants are measurements only.
export function candidateSources(source: string): [string, string][] {
  const replace = (from: string, to: string) => {
    if (!source.includes(from)) throw new Error(`Missing source marker: ${from}`)
    return source.replace(from, to)
  }
  const loop = /    for \(int i = 0; i < 16; i\+\+\) \{\s*if \(i >= int\(uLightSteps\)\) break;([\s\S]+?)\n    \}/
  const match = source.match(loop)
  if (!match) throw new Error('Missing light loop')
  const unrolled = source.replace(loop, Array.from({ length: 16 }, (_, i) =>
    `    if (${i} < int(uLightSteps)) {${match[1].replaceAll('float(i)', `${i}.0`)}\n    }`).join('\n'))
  const clip = `    if (toStar.x != 0.0) path = min(path, (sign(toStar.x) - p.x) / toStar.x);
    if (toStar.y != 0.0) path = min(path, (sign(toStar.y) - p.y) / toStar.y);
    if (toStar.z != 0.0) path = min(path, (sign(toStar.z) - p.z) / toStar.z);`
  return [
    ['noLightMarchDiagnostic', replace('return scatter * nebulaLightTransmittance(p, toStar, distanceToStar);', 'return scatter;')],
    ['flatGasColorDiagnostic', replace('gas * nebulaGasColor(medium.r, p, scatter) * uEmissiveIntensity', 'gas * vec3(1.0) * uEmissiveIntensity')],
    ['noTemporalPositionDiagnostic', replace('if (temporalRay) {', 'if (false) {')],
    ['unrolledLightSteps', unrolled],
    ['insideStarClip', replace(clip, `    if (any(greaterThanEqual(abs(uStarLocal), vec3(1.0)))) {\n${clip}\n    }`)]
  ]
}

import { Color, FloatType, GLSL3, Mesh, NoBlending, OrthographicCamera, PlaneGeometry, ShaderMaterial, UniformsUtils, WebGLRenderTarget } from 'three'
