const stats = (values: number[]) => { const sorted = values.slice().sort((a,b)=>a-b); return {count:values.length,p50:sorted[15],p95:sorted[30],max:sorted[31]} }
const owner = (object: any, id: number) => { for(;object;object=object.parent)if(object.model?.getAttribute('id')===id)return true;return false }
export async function diagnose(actorId: number) {
  const c=getInitializedSimulationRuntime()!.container,engine:any=c.get(Tokens.Engine),renderer=c.get(Tokens.Renderer)
