  const gl=renderer.getContext() as WebGL2RenderingContext,draw=renderer.render
  const savedTarget=renderer.getRenderTarget(),savedAuto=renderer.autoClear,savedAlpha=renderer.getClearAlpha(),savedColor=renderer.getClearColor(new Color())
  const targets:WebGLRenderTarget[]=[],materials:ShaderMaterial[]=[]
  const copyMaterial=new ShaderMaterial({glslVersion:GLSL3,uniforms:{map:{value:null}},depthTest:false,depthWrite:false,blending:NoBlending,
    vertexShader:'void main(){gl_Position=vec4(position.xy,0.0,1.0);}',
    fragmentShader:'uniform sampler2D map;out vec4 color;void main(){color=texelFetch(map,ivec2(gl_FragCoord.xy),0);}'})
