      const out=renderer.getRenderTarget()
      if(!out||out.texture.name!=='DepthVolume reduced HDR')return
      source=object.material.fragmentShader;defines={...object.material.defines};uniforms={}
      for(const [name,u]of Object.entries(object.material.uniforms)as any)uniforms[name]=u.value?.isTexture?{value:u.value}:UniformsUtils.clone({u}).u
      const depth=uniforms.uSceneDepth.value,copy=new WebGLRenderTarget(depth.image.width,depth.image.height,{type:FloatType,depthBuffer:false,minFilter:depth.minFilter,magFilter:depth.magFilter})
      targets.push(copy);renderer.setRenderTarget(copy);copyMaterial.uniforms.map.value=depth;draw.call(renderer,copyMesh,copyCamera);renderer.setRenderTarget(out)
      uniforms.uSceneDepth.value=copy.texture
      width=uniforms.uResolution.value.x;height=uniforms.uResolution.value.y
      actualTarget={width:out.width,height:out.height,type:out.texture.type,count:out.textures.length,viewport:out.viewport.toArray()}
