    const values:any={};for(const[name,u]of Object.entries(uniforms)as any)values[name]=u.value?.isTexture?{texture:true,width:u.value.image.width,height:u.value.image.height,depth:u.value.image.depth}:u.value?.toArray?u.value.toArray():u.value
