// Throwaway hypotheses for bounded normalized texture inputs captured by the probe.
export function candidateSources(source: string): [string, string][] {
  const cutoff = 'if (tau >= 12.0) return 0.0;'
  if(!source.includes(cutoff))throw new Error('Missing light cutoff')
  const loop = /    for \(int i = 0; i < 16; i\+\+\) \{\s*if \(i >= int\(uLightSteps\)\) break;([\s\S]+?)\n    \}/
  const match=source.match(loop)
  if(!match)throw new Error('Missing light loop')
  const uncutLoop=match[0].replace(cutoff,'')
  const bound='(max(uDensityScale * uGasAbsorption, 0.0) + max(uDustStrength, 0.0)) * path * uShadowStrength'
  const split=source.replace(match[0],`    if (${bound} < 11.0) {\n${uncutLoop}\n      return exp(-tau);\n    }\n${match[0]}`)
  const unrolled=source.replace(match[0],Array.from({length:16},(_,i)=>`    if (${i} < int(uLightSteps)) {${match[1].replaceAll('float(i)',`${i}.0`).replace(cutoff,'')}\n    }`).join('\n'))
  return [
    ['noLightCutoffDiagnostic',source.replace(cutoff,'')],
    ['boundedLightSplit',split],
    ['uncutUnrolledDiagnostic',unrolled]
  ]
}

