    if(density.type!==1009||density.format!==1030||(density.internalFormat!==null&&density.internalFormat!=='RG8'))throw new Error('Bound hypothesis requires normalized RG8 field')
    const snapshot=state(),output=new WebGLRenderTarget(width,height,{count:2,type:FloatType,depthBuffer:false});targets.push(output)
    const make=(fragmentShader:string)=>{
      const m=new ShaderMaterial({glslVersion:volume.material.glslVersion,vertexShader:volume.material.vertexShader,fragmentShader,uniforms,defines,side:volume.material.side,depthTest:false,depthWrite:false,blending:NoBlending})
      materials.push(m);return m
    }
    const render=(material:ShaderMaterial)=>{renderer.setRenderTarget(output);renderer.setClearColor(0,0);renderer.clear(true,false,false);mesh.material=material;draw.call(renderer,mesh,camera)}
    const measure=async(material:ShaderMaterial)=>{
      const timer=new GpuTimer(gl),samples:number[]=[]
      try{
        for(let i=0;i<6;i++){render(material);await new Promise(r=>setTimeout(r,0))}
        for(let i=0;i<32;i++){timer.measure(()=>render(material));await new Promise(r=>setTimeout(r,0));samples.push(...timer.poll())}
        const deadline=performance.now()+30000
        while(timer.pendingCount){await new Promise(r=>setTimeout(r,16));samples.push(...timer.poll());if(performance.now()>deadline)throw new Error('GPU timer timeout')}
        if(samples.length!==32)throw new Error('Incomplete timings')
        return {summary:stats(samples),samples}
      }finally{timer.dispose()}
    }
    const baseline=make(source);render(baseline)
    const reference=[read(output),read(output,1)],depthBefore=read(targets[0])
    const compare=(pixels:Float32Array,expected:Float32Array)=>{
      const bits=new Uint32Array(pixels.buffer),ebits=new Uint32Array(expected.buffer)
      let differentBits=0,maxError=0,error=0,signal=0
      for(let i=0;i<pixels.length;i++){if(bits[i]!==ebits[i])differentBits++;const delta=Math.abs(pixels[i]-expected[i]);maxError=Math.max(maxError,delta);error+=delta;signal+=Math.abs(expected[i])}
      return {differentBits,maxError,relativeError:error/Math.max(signal,1e-20),signal}
    }
    if(!reference[0].some(v=>v>0)||!reference[1].some(v=>v!==0))throw new Error('Empty color or representative-position fixture')
    const rows=[]
    for(const [name,material]of [['baseline',baseline],...candidateSources(source).map(([n,s])=>[n,make(s)]),['baselineRepeat',baseline]]as [string,ShaderMaterial][]){
      render(material);const image={color:compare(read(output),reference[0]),position:compare(read(output,1),reference[1])},timing=await measure(material)
      rows.push({name,image,...timing});console.info('NEBULA_MARCH',actorId,name,JSON.stringify({image,summary:timing.summary}))
    }
    if(read(targets[0]).some((v,i)=>v!==depthBefore[i])||gl.getError())throw new Error('Depth drift or GL error')
    const values:any={};for(const[name,u]of Object.entries(uniforms)as any)values[name]=u.value?.isTexture?{texture:true,width:u.value.image.width,height:u.value.image.height,depth:u.value.image.depth}:u.value?.toArray?u.value.toArray():u.value
    return {actorId,width,height,snapshot,actualTarget,defines,uniforms:values,rows,sceneDepthUnchanged:true}
  }finally{
    renderer.render=draw;materials.forEach(m=>m.dispose());targets.forEach(t=>t.dispose());copyMesh.geometry.dispose();copyMaterial.dispose()
    renderer.setRenderTarget(savedTarget);renderer.setClearColor(savedColor,savedAlpha);renderer.autoClear=savedAuto;engine.start()
  }
}

