// Temporary diagnostic probe: wraps the real runtime; no application changes.
import { getInitializedSimulationRuntime } from '/src/ui/runtime/simulationRuntime'
import { Tokens } from '/src/core/providers/tokens'
import { GpuTimer } from '/tests/browser/gpuTimer'
import { snapshot } from '/tests/browser/scenarioSoak.browser'
import { Vector3 } from 'three'
import { AsteroidImpostorLibrary } from '/src/core/renderables/DetailedRingStreamingSystem/impostors/AsteroidImpostorLibrary'
import { fromAstronomicalUnits, toThreeJSUnits } from '/src/core/helpers/scaling'

const runtime = () => getInitializedSimulationRuntime()!.container
export const preparations: { ms: number; frames: number; jobs: number }[] = []
export function installEarlyDensity() {
  const original = AsteroidImpostorLibrary.prototype.prepareInitial
  AsteroidImpostorLibrary.prototype.prepareInitial = async function () {
    await original.call(this)
    const queue = runtime().get(Tokens.NebulaBakeQueue), started = performance.now(), jobs = queue.pendingCount
    let frames = 0
    while (queue.pendingCount) {
      queue.pumpFrame(); frames++
      await new Promise(resolve => setTimeout(resolve, 0))
      if (performance.now() - started > 60000) throw new Error('Initial density preparation timed out')
    }
    preparations.push({ ms: performance.now() - started, frames, jobs })
  }
}
const summarize = (xs: number[]) => {
  const s = xs.slice().sort((a, b) => a - b)
  return { count: s.length, p50: s[Math.ceil(s.length * .5) - 1], p95: s[Math.ceil(s.length * .95) - 1], max: s.at(-1) }
}
const label = (o: any) => {
  const path = []
  for (let p = o; p; p = p.parent) path.push(`${p.name || p.constructor.name}${p.model ? ':' + p.model.getAttribute('id') : ''}`)
  return path.reverse().join('/')
}
export function state() {
  const c = runtime(), queue = c.get(Tokens.NebulaBakeQueue)
  const belts: unknown[] = [], streamers: unknown[] = []
  c.get(Tokens.Scene).traverse((object: any) => {
    if (object.constructor.name === 'AsteroidBelt') belts.push({ label: label(object), lod: object.lodState, streamer: object.streamer !== null, visible: object.streamer?.visible })
    if (object.constructor.name === 'AsteroidRingSystem') streamers.push({ label: label(object), info: object.getDebugInfo() })
  })
  return { ...snapshot(), pending: queue.pendingCount, allocated: queue.allocatedBytes,
    belts, streamers,
    camera: c.get(Tokens.Camera).position.toArray(), orientation: c.get(Tokens.Camera).quaternion.toArray(), volumes: c.get(Tokens.DepthVolumeRegistry).volumes().map((v: any) => ({
      id: v.id, label: label(v), visible: v.visible, position: v.getWorldPosition(new Vector3()).toArray(),
      scale: v.getWorldScale(new Vector3()).toArray(), resolution: v.resolutionScale,
      defines: v.material?.defines, ready: v.material?.uniforms?.uDensityReady?.value,
      lod: v.material?.uniforms?.uLodBlend?.value
    })) }
}

export function setView(actorId: number, kind: 'planet' | 'belt' | 'cloud') {
  const c = runtime(), scene = c.get(Tokens.Scene), camera = c.get(Tokens.Camera)
  let target: any
  scene.traverse((object: any) => {
    if (!target && object.model?.getAttribute('id') === actorId) target = object
  })
  if (!target) throw new Error(`Actor ${actorId} is absent`)
  const center = target.getWorldPosition(new Vector3())
  c.get(Tokens.CameraController).stopFollowing()
  if (kind === 'planet') {
    const radius = toThreeJSUnits(target.model.physicalObject.getAttribute('radius'))
    camera.position.copy(center).add(new Vector3(1, .6, 1).normalize().multiplyScalar(radius * 3))
    camera.lookAt(center)
  } else if (kind === 'belt') {
    const data = target.model.renderingObject.getAttribute('data')
    const radius = fromAstronomicalUnits((data.innerRadiusAu + data.outerRadiusAu) / 2)
    let belt = target
    target.traverse((object: any) => { if (object.constructor.name === 'AsteroidBelt') belt = object })
    camera.position.copy(new Vector3(radius, 0, 0).applyMatrix4(belt.matrixWorld))
    camera.lookAt(center)
  } else {
    camera.position.copy(center).add(new Vector3(fromAstronomicalUnits(.15), fromAstronomicalUnits(.02), 0))
    camera.lookAt(center)
  }
  c.get(Tokens.CameraCollision).reset()
  return { actorId, kind, center: center.toArray(), requestedPosition: camera.position.toArray(), name: target.model.getAttribute('name') }
}

export async function profile(frames = 60, mode = 'passes', orbit = false) {
  const c = runtime(), engine: any = c.get(Tokens.Engine), renderer = c.get(Tokens.Renderer)
  const camera = c.get(Tokens.Camera), origin = camera.position.clone(), orientation = camera.quaternion.clone()
  const pp: any = c.get(Tokens.Postprocessing), gl = renderer.getContext() as WebGL2RenderingContext
  const timers = new Map<string, GpuTimer>(), cpu: Record<string, number[]> = {}, gpu: Record<string, number[]> = {}
  const restore: (() => void)[] = [], intervals: number[] = [], timeline: any[] = [], counts: any[] = []
  const draws: Record<string, any> = {}
  let active = true, frame = 0, previous = 0, failure: unknown
  const timer = (key: string) => {
    if (!timers.has(key)) { timers.set(key, new GpuTimer(gl)); gpu[key] = [] }
    return timers.get(key)!
  }
  const wrap = (obj: any, key: string, name: string | ((args: any[]) => string), gpuEnabled = false) => {
    const original = obj[key]
    obj[key] = function (...args: any[]) {
      if (!active) return original.apply(this, args)
      const n = typeof name === 'function' ? name(args) : name
      const start = performance.now()
      let result: unknown
      if (gpuEnabled) timer(n).measure(() => { result = original.apply(this, args) })
      else result = original.apply(this, args)
      ;(cpu[n] ??= []).push(performance.now() - start)
      return result
    }
    restore.push(() => { obj[key] = original })
  }
  try {
    new GpuTimer(gl).dispose()
    for (const [i, p] of pp.composer.passes.entries()) {
      wrap(p, 'render', `${i}:${p.name}`, mode === 'passes')
      if (p.name === 'DepthVolumePass' && mode === 'volumes') {
        wrap(p.scaled, 'render', args => 'volume:' + label(args[3]), true)
      }
    }
    if (mode === 'draws') {
      let mainPass = false
      const pass = pp.composer.passes.find((p: any) => p.name === 'RenderPass')
      const renderPass = pass.render
      pass.render = function (...args: any[]) {
        mainPass = true
        try { return renderPass.apply(this, args) } finally { mainPass = false }
      }
      restore.push(() => { pass.render = renderPass })
      const renderDirect = renderer.renderBufferDirect
      renderer.renderBufferDirect = function (...args: any[]) {
        if (!active || !mainPass) return renderDirect.apply(this, args)
        const [, , geometry, material, object] = args
        const key = `${label(object)}#${object.id}`
        draws[key] = { material: material.name || material.type, defines: material.defines,
          count: object.count ?? 1, indices: geometry.index?.count, vertices: geometry.attributes.position?.count,
          drawRange: geometry.drawRange, transparent: material.transparent, side: material.side }
        let result: any
        timer(key).measure(() => { result = renderDirect.apply(this, args) })
        return result
      }
      restore.push(() => { renderer.renderBufferDirect = renderDirect })
    }
    if (mode === 'volumeDraws') {
      const render = renderer.render
      renderer.render = function (object: any, view: any) {
        if (!active || typeof object.bindSceneDepth !== 'function') return render.call(this, object, view)
        const u = object.material?.uniforms
        const phase = u?.uLowResolutionEnabled?.value > 0 ? 'reconstruct' : 'march'
        const key = `${label(object)}:${phase}`
        timer(key).measure(() => render.call(this, object, view))
      }
      restore.push(() => { renderer.render = render })
    }
    for (const [token, methods] of [
      [Tokens.SceneManager, ['update', 'updateView', 'updateMarkers']],
      [Tokens.SceneObserver, ['tick']], [Tokens.NebulaBakeQueue, ['pumpFrame']],
      [Tokens.AsteroidImpostorLibrary, ['pumpFrame']]
    ] as const) {
      const obj = c.get(token as any)
      for (const key of methods) wrap(obj, key, `${obj.constructor.name}.${key}`, false)
    }
    const initial = state(), started = performance.now()
    c.get(Tokens.Scene).traverse((object: any) => {
      if (object.pool?.updateNearVisibility) wrap(object.pool, 'updateNearVisibility', `nearVisibility:${label(object)}`, false)
    })
    const autoReset = renderer.info.autoReset
    renderer.info.autoReset = false
    restore.push(() => { renderer.info.autoReset = autoReset })
    const originalFrame = engine.renderFrame
    restore.push(() => { engine.renderFrame = originalFrame })
    await new Promise<void>(resolve => {
      engine.renderFrame = function () {
        if (!active) return originalFrame.call(this)
        try {
          for (const [key, t] of timers) gpu[key].push(...t.poll())
          const now = performance.now()
          if (previous) intervals.push(now - previous)
          previous = now
          if (orbit) {
            const angle = frame / frames * Math.PI * 2
            camera.position.set(origin.x * Math.cos(angle) + origin.z * Math.sin(angle), origin.y,
              origin.z * Math.cos(angle) - origin.x * Math.sin(angle))
            camera.lookAt(0, 0, 0)
          }
          renderer.info.reset()
          if (mode === 'frame') timer('whole-frame').measure(() => originalFrame.call(this))
          else originalFrame.call(this)
          ;(cpu['whole-frame'] ??= []).push(performance.now() - now)
          counts.push({ ...renderer.info.render })
          if (frame % 16 === 0 || frame === frames - 1) timeline.push({ sampleFrame: frame, sinceStart: performance.now() - started, ...state() })
          frame++
          if (frame >= frames) { active = false; renderer.setAnimationLoop(null); resolve() }
        } catch (e) { failure = e; active = false; renderer.setAnimationLoop(null); resolve() }
      }
    })
    // onFrameRendered schedules the next callback after renderFrame returns.
    engine.stop()
    if (failure) throw failure
    const deadline = performance.now() + 30_000
    while ([...timers.values()].some(t => t.pendingCount)) {
      await new Promise(resolve => setTimeout(resolve, 16))
      for (const [key, t] of timers) gpu[key].push(...t.poll())
      if (performance.now() > deadline) throw new Error('GPU timers did not complete')
    }
    const error = gl.getError()
    if (error !== gl.NO_ERROR) throw new Error(`WebGL error ${error}`)
    return { mode, orbit, frames, initial, final: state(), timeline, counts, intervals, draws,
      summary: { intervals: summarize(intervals), cpu: Object.fromEntries(Object.entries(cpu).map(([k, xs]) => [k, summarize(xs)])),
        gpu: Object.fromEntries(Object.entries(gpu).map(([k, xs]) => [k, summarize(xs)])) }, cpu, gpu }
  } finally {
    active = false
    for (const undo of restore.reverse()) undo()
    for (const t of timers.values()) t.dispose()
    camera.position.copy(origin); camera.quaternion.copy(orientation)
    engine.start()
  }
}

