import {readFile,writeFile}from'node:fs/promises'
import {createHash}from'node:crypto'
import {execFileSync}from'node:child_process'

const prefix='benchmark-results/heavy-scenes/',destination='docs/benchmarks/nebula-light-bound-2026-10-23.json'
const base='6700d579356203315c65a351bc6891c326521993',provenance=[]
const hash=b=>createHash('sha256').update(b).digest('hex')
const decode=b=>b[0]===255&&b[1]===254?b.subarray(2).toString('utf16le'):b.toString('utf8').replace(/^\uFEFF/,'')
const normalize=t=>t.replaceAll('\r\n','\n')
async function source(path,json=true){const b=await readFile(path);provenance.push({path,bytes:b.length,sha256:hash(b)});const t=decode(b);if(t.includes('\0'))throw Error('NUL in '+path);return json?JSON.parse(t):t}
function browser(report){
  const rows=[]
  const walk=suite=>{
    for(const child of suite.suites||[])walk(child)
    for(const spec of suite.specs||[])for(const test of spec.tests||[])for(const result of test.results||[]){
      const a=Object.fromEntries((result.attachments||[]).filter(a=>a.body&&a.contentType==='application/json').map(a=>[a.name,JSON.parse(Buffer.from(a.body,'base64').toString())]))
      const d=a['browser-diagnostics'],focused=spec.title.startsWith('nebula ')
      rows.push({title:spec.title,status:result.status,durationMs:result.duration,retry:result.retry,errors:result.errors,
        environment:focused?a['webgl-environment']:undefined,probe:focused?a['probe-result']:a['probe-result']?.status,
        diagnostics:d?{pageErrors:d.pageErrors,failedRequests:d.failedRequests,warnings:d.warningClassifications,errors:d.console.filter(x=>x.type==='error')}:undefined})
    }
  }
  report.suites.forEach(walk);return {stats:report.stats,errors:report.errors,rows}
}
function timings(samples,summary){
  const sorted=samples.slice().sort((a,b)=>a-b)
  if(sorted.length!==32||summary.count!==32||sorted.some(x=>!Number.isFinite(x)||x<=0)||sorted[15]!==summary.p50||sorted[30]!==summary.p95||sorted[31]!==summary.max)throw Error('Invalid GPU samples/statistics')
}
function cleanBrowser(run,expected){
  const unexpectedRequests=row=>row.diagnostics?.failedRequests.some(request=>!(
    row.title==='native texture fetch cancellation and cube orientation'&&
    /^http:\/\/127\.0\.0\.1:\d+\/held-texture\.png$/.test(request.url)&&request.failure==='net::ERR_ABORTED'))
  if(run.stats.expected!==expected||run.stats.unexpected||run.stats.skipped||run.stats.flaky||run.errors.length||run.rows.length!==expected||run.rows.some(r=>r.status!=='passed'||r.retry||r.errors?.length||r.diagnostics?.pageErrors.length||unexpectedRequests(r)||r.diagnostics?.errors.length))throw Error('Incomplete browser verification')
}
function views(run,green){
  if(run.rows.length!==2||run.errors.length||run.warnings.length||run.assetFailures.length)throw Error('Unclean cloud comparison')
  for(const scene of run.rows){
    if(scene.frozen.length!==2)throw Error('Missing original/moved view')
    for(const row of scene.frozen){
      for(const key of ['baseline','optimized'])timings(row.samples[key],row.summary[key])
      for(const output of [row.image,row.repeat])for(const key of ['color','position'])if(output[key].differentBits||output[key].maxError||output[key].signal<=0)throw Error('HDR/position mismatch')
      if(!row.sceneDepthUnchanged||JSON.stringify(row.resourcesBefore)!==JSON.stringify(row.resourcesAfter)||row.actualTarget.type!==1016||row.actualTarget.count!==2||row.width!==640||row.height!==360)throw Error('Working MRT/depth/resource mismatch')
      if(green&&row.summary.optimized.p50/row.summary.baseline.p50>0.98)throw Error('Local speed gate failed')
      if(!green&&row.summary.optimized.p50/row.summary.baseline.p50<=0.98)throw Error('Unchanged-version RED unexpectedly passed')
    }
  }
}
async function verify(r){
  for(const p of r.provenance){const b=await readFile(p.path);if(b.length!==p.bytes||hash(b)!==p.sha256)throw Error('Changed input '+p.path);if(p.path in r.sourceSnapshots&&decode(b)!==r.sourceSnapshots[p.path])throw Error('Embedded source mismatch '+p.path)}
  const old=normalize(execFileSync('git',['show',base+':src/core/renderables/Nebula/material/shader/chunks/NebulaLighting.ts'],{encoding:'utf8'}))
  if(r.baselineProof.base!==base||r.baselineProof.normalizedSha256!==hash(old)||normalize(r.sourceSnapshots[prefix+'nebula-light-baseline-2026-10-23.ts'])!==old)throw Error('Baseline Git mismatch')
  for(const run of Object.values(r.diagnosis)){
    if(run.outcome!=='completed'||run.errors.length||run.warnings.length||run.assetFailures.length)throw Error('Unclean diagnosis')
    for(const row of run.rows)for(const v of row.rows||[])timings(v.samples,v.summary)
  }
  if(r.red.outcome!=='failed'||!r.red.failure?.includes('performance gate: expected >=2%'))throw Error('Missing performance RED')
  views(r.red,false)
  if(r.production.outcome!=='completed')throw Error('Missing GREEN')
  views(r.production,true)
  cleanBrowser(r.preimplementation,1)
  for(const run of Object.values(r.regression)){
    cleanBrowser(run,4)
    const p=run.rows.find(x=>x.title==='nebula bounded light')?.probe?.result
    if(!p||p.cases!==234||p.opaqueCases<51||p.programs!==1||!Number.isFinite(p.maxError))throw Error('Missing analytic optical/texture switch checks')
  }
  cleanBrowser(r.verification.fullBrowser,46)
  if(r.verification.steps.length!==5||r.verification.steps.some(s=>s.exitCode!==0))throw Error('Verification process failed/incomplete')
  const logs=r.verification.logs
  if(!/Tests\s+5559 passed\s*\|\s*7 skipped/.test(logs['full-test'])||logs['full-test'].includes('--maxWorkers')||!/Tests\s+\d+ passed/.test(logs['focused-unit'])||!/built in [\d.]+s/.test(logs.build))throw Error('Missing default verification')
  if(r.review.status==='completed'&&(!Array.isArray(r.review.rulings)||r.review.rulings.length!==r.review.declined.length||r.review.unresolvedFindings.length))throw Error('Review decisions incomplete')
